    path: str | os.PathLike[str],
    store: MemoryStore,
    *,
    fmt: str | None = None,
    strict: bool = False,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> ImportResult:
    """Импортирует выписку в store.

    Формат определяется по заголовку, либо берётся из fmt. Дубли — строки, для которых в store
    уже есть операция с той же датой, суммой и описанием (по количеству). В строгом режиме первая
    ошибка строки бросает StatementRowError до записи; иначе ошибки попадают в ImportResult.errors.
    """
    if fmt is not None and fmt not in FORMATS:
        raise UnknownFormatError(f"unknown format {fmt!r}")
    clock = clock or SystemClock()
    imported_at = clock.now()
    text, encoding = _read_text(path)
    spec, cols = _detect(text, fmt)
    txs, errors = _parse_rows(text, spec, cols, imported_at, strict)

    remaining = Counter(_dedup_key(tx) for tx in store.all())
    to_add: list[Transaction] = []
    duplicates = 0
    for tx in txs:
        key = _dedup_key(tx)
        if remaining[key] > 0:
            remaining[key] -= 1
            duplicates += 1
            continue
        if categorizer is not None:
            category = categorizer.categorize(tx)
            if category is not None:
                tx = replace(tx, category=category)
        to_add.append(tx)

    if to_add:
        store.add_many(to_add)
    logger.info("imported %d transactions from %s", len(to_add), path)
    return ImportResult(
        format=spec.name,
        encoding=encoding,
        added=len(to_add),
        duplicates=duplicates,
        errors=errors,
    )


def import_csv(
    path: str | os.PathLike[str],
    store: MemoryStore,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> int:
    """Импортирует выписку «Новы» в store и возвращает число добавленных транзакций."""
    return import_statement(
        path, store, fmt="nova", strict=True, categorizer=categorizer, clock=clock
    ).added

"""Импорт банковских выписок.

Поддерживаются три формата (определяются по заголовку, см. detect_format):

    nova:        date,amount,description
                 2026-03-01,-350.00,Кофейня Зерно
    sfera:       Дата;Сумма;Описание
                 01.03.2026;-1 200,50;Магазин Лента
    sfera_split: Дата;Описание;Приход;Расход
                 03.03.2026;Кофе;;150,00
"""

from __future__ import annotations

import csv
import datetime as dt
import io
import logging
import os
import re
from collections import Counter
from collections.abc import Callable
from dataclasses import dataclass, field, replace
from decimal import Decimal, InvalidOperation
from pathlib import Path

from ledger.clock import Clock, SystemClock
from ledger.errors import StatementError, StatementRowError, UnknownFormatError, ValidationError
from ledger.models import Transaction, parse_amount, to_money
from ledger.rules import Categorizer, normalize_text
from ledger.storage import MemoryStore

logger = logging.getLogger(__name__)

# Пробел, неразрывный пробел и узкий неразрывный пробел как разделители тысяч.
_SFERA_AMOUNT = re.compile(r"([+-]?)(\d{1,3}(?:[   ]\d{3})+|\d+)(?:[.,](\d{1,2}))?", re.ASCII)
_SFERA_DATE = re.compile(r"(\d{2})\.(\d{2})\.(\d{4})", re.ASCII)
_THOUSANDS_SEPARATORS = re.compile(r"[   ]")

# Беззнаковый ноль в колонке «Приход» или «Расход»: служебная строка банка, если так в обеих.
_UNSIGNED_ZERO = re.compile(r"0+(?:[.,]0{1,2})?", re.ASCII)

Row = list[str]
# None — строка служебная и пропускается без следа.
Parser = Callable[[Row, dict[str, int], dt.datetime], Transaction | None]


@dataclass(frozen=True)
class RowError:
    """Ошибка одной строки выписки, собранная в режиме не строгого импорта.

    raw — текст записи как в файле: без BOM и без переводов строки; многострочная запись
    соединена через «\\n».
    """

    line_no: int
    message: str
    raw: str = ""


@dataclass(frozen=True)
class ImportResult:
    """Итог импорта: формат и кодировка файла, счётчики, ошибки строк и добавленные транзакции.

    transactions — добавленные транзакции в порядке строк файла; при dry_run у них id=None.
    """

    format: str
    encoding: str
    added: int
    duplicates: int
    errors: list[RowError]
    transactions: list[Transaction] = field(default_factory=list)


@dataclass(frozen=True)
class _Format:
    name: str
    delimiter: str
    columns: tuple[str, ...]  # обязательные колонки, в нижнем регистре
    parse: Parser


def _cell(row: Row, cols: dict[str, int], name: str) -> str:
    index = cols[name]
    if index >= len(row):
        raise StatementError("not enough fields")
    return row[index]


def _make_transaction(
    date: dt.date, amount: Decimal, description: str, imported_at: dt.datetime
) -> Transaction:
    try:
        return Transaction(
            date=date,
            amount=amount,
            description=description.strip(),
            imported_at=imported_at,
        )
    except (ValidationError, InvalidOperation) as exc:
        raise StatementError(str(exc)) from exc


def _parse_nova(row: Row, cols: dict[str, int], imported_at: dt.datetime) -> Transaction:
    date_text = _cell(row, cols, "date").strip()
    try:
        date = dt.date.fromisoformat(date_text)
    except ValueError as exc:
        raise StatementError(f"invalid date {date_text!r}") from exc
    try:
        amount = parse_amount(_cell(row, cols, "amount"))
    except ValidationError as exc:
        raise StatementError(str(exc)) from exc
    return _make_transaction(date, amount, _cell(row, cols, "description"), imported_at)


def _sfera_date(text: str) -> dt.date:
    match = _SFERA_DATE.fullmatch(text.strip())
    if match is None:
        raise StatementError(f"invalid date {text.strip()!r}, expected DD.MM.YYYY")
    day, month, year = (int(part) for part in match.groups())
    try:
        return dt.date(year, month, day)
    except ValueError as exc:
        raise StatementError(f"invalid date {text.strip()!r}") from exc


def _sfera_amount(text: str, *, signed: bool) -> Decimal:
    stripped = text.strip()
    match = _SFERA_AMOUNT.fullmatch(stripped)
    if match is None or (not signed and match.group(1)):
        raise StatementError(f"invalid amount {stripped!r}")
    sign, whole, frac = match.groups()
    digits = _THOUSANDS_SEPARATORS.sub("", whole)
    try:
        return to_money(Decimal(f"{sign}{digits}.{frac or '0'}"))
    except (ValidationError, InvalidOperation) as exc:
        raise StatementError(str(exc)) from exc


def _parse_sfera(row: Row, cols: dict[str, int], imported_at: dt.datetime) -> Transaction:
    date = _sfera_date(_cell(row, cols, "дата"))
    amount = _sfera_amount(_cell(row, cols, "сумма"), signed=True)
    return _make_transaction(date, amount, _cell(row, cols, "описание"), imported_at)


def _parse_sfera_split(row: Row, cols: dict[str, int], imported_at: dt.datetime) -> Transaction:
    date = _sfera_date(_cell(row, cols, "дата"))
    income = _split_cell(_cell(row, cols, "приход"))
    expense = _split_cell(_cell(row, cols, "расход"))
    if (income is None) == (expense is None):
        raise StatementError("exactly one of Приход and Расход must be filled")
    amount = income if income is not None else -expense
    return _make_transaction(date, amount, _cell(row, cols, "описание"), imported_at)


def _split_cell(text: str) -> Decimal | None:
    """Сумма из колонки «Приход» или «Расход» без знака; пустая или нулевая ячейка — None."""
    if not text.strip():
        return None
    amount = _sfera_amount(text, signed=False)
    return None if amount == 0 else amount


_NOVA = _Format("nova", ",", ("date", "amount", "description"), _parse_nova)
_SFERA = _Format("sfera", ";", ("дата", "сумма", "описание"), _parse_sfera)
_SFERA_SPLIT = _Format(
    "sfera_split", ";", ("дата", "описание", "приход", "расход"), _parse_sfera_split
)
FORMATS: dict[str, _Format] = {f.name: f for f in (_NOVA, _SFERA, _SFERA_SPLIT)}


def _read_text(path: str | os.PathLike[str]) -> tuple[str, str]:
    """Читает файл целиком: UTF-8 (BOM снимается), иначе cp1251. Возвращает текст и кодировку."""
    try:
        raw = Path(path).read_bytes()
    except OSError as exc:
        raise StatementError(f"cannot read {path}: {exc}") from exc
    try:
        return raw.decode("utf-8-sig"), "utf-8"
    except UnicodeDecodeError:
        pass
    try:
        return raw.decode("cp1251"), "cp1251"
    except UnicodeDecodeError as exc:
        raise UnknownFormatError(f"cannot decode {path} as UTF-8 or cp1251") from exc


def _detect(text: str, fmt: str | None) -> tuple[_Format, dict[str, int]]:
    """Находит формат по заголовку (строка 1) и возвращает его вместе с индексами колонок."""
    candidates = [FORMATS[fmt]] if fmt is not None else list(FORMATS.values())
    matches: list[tuple[_Format, dict[str, int]]] = []
    for spec in candidates:
        # Каждый формат разбирает заголовок своим разделителем; разделитель не угадываем.
        header = next(csv.reader(io.StringIO(text, newline=""), delimiter=spec.delimiter), [])
        names = [cell.strip().casefold() for cell in header]
        if any(names.count(column) > 1 for column in spec.columns):
            raise UnknownFormatError(f"duplicated column in header for format {spec.name!r}", line_no=1)
        if all(column in names for column in spec.columns):
            matches.append((spec, {column: names.index(column) for column in spec.columns}))
    if len(matches) == 1:
        return matches[0]
    if fmt is not None:
        raise UnknownFormatError(f"header does not match format {fmt!r}", line_no=1)
    if not matches:
        raise UnknownFormatError("unknown statement header", line_no=1)
    raise UnknownFormatError("header matches several formats", line_no=1)


def detect_format(path: str | os.PathLike[str]) -> str:
    """Возвращает имя формата выписки по заголовку: 'nova', 'sfera' или 'sfera_split'."""
    text, _ = _read_text(path)
    spec, _ = _detect(text, None)
    return spec.name


def normalize_description(text: str) -> str:
    """Нормализация описания для сравнения на дубли; та же, что в правилах категоризации."""
    return normalize_text(text)


def _dedup_key(tx: Transaction) -> tuple[dt.date, Decimal, str]:
    return (tx.date, tx.amount, normalize_description(tx.description))


def _parse_rows(
    text: str,
    spec: _Format,
    cols: dict[str, int],
    imported_at: dt.datetime,
    strict: bool,
) -> tuple[list[Transaction], list[RowError]]:
    reader = csv.reader(io.StringIO(text, newline=""), delimiter=spec.delimiter)
    next(reader, None)  # заголовок уже разобран в _detect
    txs: list[Transaction] = []
    errors: list[RowError] = []
    while True:
        # line_num после чтения указывает на последнюю физическую строку записи,
        # поэтому номер начала берём до чтения.
        line_no = reader.line_num + 1
        row = next(reader, None)
        if row is None:
            break
        if not any(cell.strip() for cell in row):
            continue
        try:
            txs.append(spec.parse(row, cols, imported_at))
        except StatementError as exc:
            if strict:
                raise StatementRowError(exc.message, line_no=line_no) from exc
            errors.append(RowError(line_no=line_no, message=exc.message))
    return txs, errors


def import_statement(
    path: str | os.PathLike[str],
    store: MemoryStore,
    *,
    fmt: str | None = None,
    strict: bool = False,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
